package com.trianguloy.urlchecker.modules.list;

import android.net.Uri;
import android.net.UrlQuerySanitizer;
import android.view.View;
import android.widget.Button;
import android.widget.LinearLayout;
import android.widget.TextView;

import com.trianguloy.urlchecker.R;
import com.trianguloy.urlchecker.activities.ModulesActivity;
import com.trianguloy.urlchecker.dialogs.MainDialog;
import com.trianguloy.urlchecker.modules.AModuleConfig;
import com.trianguloy.urlchecker.modules.AModuleData;
import com.trianguloy.urlchecker.modules.AModuleDialog;
import com.trianguloy.urlchecker.modules.DescriptionConfig;
import com.trianguloy.urlchecker.url.UrlData;
import com.trianguloy.urlchecker.utilities.methods.AndroidUtils;
import com.trianguloy.urlchecker.utilities.methods.Inflater;
import com.trianguloy.urlchecker.utilities.methods.JavaUtils;

import java.util.ArrayList;
import java.util.List;

/**
 * This module shows all parts of the url decoded
 */
public class UriPartsModule extends AModuleData {

    @Override
    public String getId() {
        return "uriparts";
    }

    @Override
    public int getName() {
        return R.string.mParts_name;
    }

    @Override
    public AModuleDialog getDialog(MainDialog cntx) {
        return new UriPartsDialog(cntx);
    }

    @Override
    public AModuleConfig getConfig(ModulesActivity cntx) {
        return new DescriptionConfig(R.string.mParts_desc);
    }
}

class UriPartsDialog extends AModuleDialog {

    private LinearLayout box;
    private final List<String> expandedGroups = new ArrayList<>();

    public UriPartsDialog(MainDialog dialog) {
        super(dialog);
    }

    @Override
    public int getLayoutId() {
        return R.layout.dialog_parts;
    }

    @Override
    public void onInitialize(View views) {
        box = views.findViewById(R.id.box);
    }

    @Override
    public void onDisplayUrl(UrlData urlData) {
        // clear
        box.removeAllViews();

        // parse
        var uri = Uri.parse(urlData.url);
        var urlQuerySanitizer = new UrlQuerySanitizer();
        // the default parseUrl doesn't remove the fragment
        if (uri.getQuery() != null) {
            urlQuerySanitizer.setAllowUnregisteredParamaters(true);
            urlQuerySanitizer.setUnregisteredParameterValueSanitizer(v -> v);
            urlQuerySanitizer.parseQuery(uri.getQuery());
        }

        // domain elements
        if (uri.getAuthority() != null || uri.getScheme() != null) {
            var domain = addGroup("Domain", -1, null);
            addPart("scheme", uri.getScheme(), domain, null);
            addPart("user info", uri.getUserInfo(), domain, null);
            addPart("host", uri.getHost(), domain, null);
            addPart("port", uri.getPort() != -1 ? String.valueOf(uri.getPort()) : null, domain, null);
        }

        // paths
        var pathSegments = uri.getPathSegments();
        if (pathSegments.size() > 0) {
            var paths = addGroup("Paths", pathSegments.size(), uri.buildUpon().path(null));
            for (var i = 0; i < pathSegments.size(); i++) {
                var pathSegment = pathSegments.get(i);

                var builder = uri.buildUpon();
                builder.path(null);
                for (int newI = 0; newI < pathSegments.size(); newI++) {
                    if (newI != i) builder.appendPath(pathSegments.get(newI));
                }
                addPart("/", pathSegment, paths, builder);
            }
        }

        // query parameters
        var parameters = urlQuerySanitizer.getParameterList();
        if (parameters.size() > 0) {
            var queries = addGroup("Parameters", parameters.size(), uri.buildUpon().query(null));
            for (var i = 0; i < parameters.size(); i++) {
                // generate same url but without this parameter
                var builder = uri.buildUpon();
                builder.query(null);
                for (var j = 0; j < parameters.size(); j++) {
                    if (i != j) builder.appendQueryParameter(parameters.get(j).mParameter, parameters.get(j).mValue);
                }
                // append the parameter
                addPart(parameters.get(i).mParameter, parameters.get(i).mValue, queries, builder);
            }
        }

        // fragment
        if (uri.getFragment() != null) {
            var fragment = addGroup("Fragment", -1, uri.buildUpon().fragment(null));
            addPart("#", uri.getFragment(), fragment, null);
        }

        setVisibility(box.getChildCount() > 0);
    }

    /**
     * Adds a collapsible group
     */
    private LinearLayout addGroup(String name, int size, Uri.Builder onDelete) {
        var title = Inflater.inflate(R.layout.uri_part, box);
        title.findViewById(R.id.key).setVisibility(View.GONE);

        var name_view = title.<TextView>findViewById(R.id.value);
        name_view.setText(name + (size <= -1 ? "" : " (" + size + ")"));
        AndroidUtils.setAsClickable(name_view);

        var delete_view = title.<Button>findViewById(R.id.delete);
        if (onDelete == null) delete_view.setVisibility(View.GONE);
        else delete_view.setOnClickListener(v -> setUrl(onDelete.build().toString()));

        var group = Inflater.<LinearLayout>inflate(R.layout.dialog_parts, box);
        group.setVisibility(expandedGroups.contains(name) ? View.VISIBLE : View.GONE);
        AndroidUtils.toggleableListener(
                title,
                v -> JavaUtils.toggleContains(expandedGroups, name),
                v -> {
                    group.setVisibility(expandedGroups.contains(name) ? View.VISIBLE : View.GONE);
                    name_view.setCompoundDrawablesRelativeWithIntrinsicBounds(expandedGroups.contains(name) ? R.drawable.arrow_down : R.drawable.arrow_right, 0, 0, 0);
                }
        );

        return group;
    }

    /**
     * Adds a part
     */
    private void addPart(String name, String value, LinearLayout container, Uri.Builder onDelete) {
        if (value == null) return;
        // create row
        var part = Inflater.inflate(R.layout.uri_part, container);

        // configure key
        var key_view = part.<TextView>findViewById(R.id.key);
        key_view.setText(name.isEmpty() ? getActivity().getString(R.string.mParts_empty) : name);
        if (!name.isEmpty()) key_view.setOnLongClickListener(longTapToCopy);

        // configure value
        var value_view = part.<TextView>findViewById(R.id.value);
        value_view.setText(value);
        AndroidUtils.setAsClickable(value_view);
        value_view.setOnClickListener(v -> setUrl(value));
        value_view.setOnLongClickListener(longTapToCopy);

        // configure delete
        var delete_view = part.<Button>findViewById(R.id.delete);
        if (onDelete != null) {
            try {
                var newUrl = onDelete.build().toString();
                delete_view.setOnClickListener(v -> setUrl(newUrl));
            } catch (UnsupportedOperationException ignored) {
                delete_view.setVisibility(View.GONE);
            }
        } else {
            delete_view.setVisibility(View.GONE);
        }
    }

    /**
     * OnLongClickListener to copy a part (textview text) to the clipboard
     */
    private final View.OnLongClickListener longTapToCopy = v -> {
        AndroidUtils.copyToClipboard(getActivity(), R.string.mParts_copy, ((TextView) v).getText().toString());
        return true;
    };

}

package com.trianguloy.urlchecker.utilities.methods;

import android.content.Context;
import android.content.Intent;
import android.net.Uri;
import android.os.Parcelable;
import android.widget.Toast;

import com.trianguloy.urlchecker.R;

import java.util.ArrayList;
import java.util.List;

/**
 * Static utilities related to urls
 */
public interface UrlUtils {

    /**
     * Returns an intent that will open the given url, with an optional package
     *
     * @param url         the url that will be opened
     * @param packageName the package that will be opened, null to let android choose
     * @return the converted intent
     */
    static Intent getViewIntent(String url, String packageName) {
        Intent intent = new Intent(Intent.ACTION_VIEW, Uri.parse(url));
        if (packageName != null) intent.setPackage(packageName);
        return intent;
    }

    /**
     * Opens an url removing this app from the chooser
     *
     * @param url  url to open
     * @param cntx base context
     */
    static void openUrlRemoveThis(String url, Context cntx) {

        // get packages that can open the url
        List<Intent> intents = new ArrayList<>();
        for (String pack : PackageUtils.getOtherPackages(getViewIntent(url, null), cntx)) {
            intents.add(getViewIntent(url, pack));
        }

        // check if none
        if (intents.isEmpty()) {
            Toast.makeText(cntx, R.string.toast_noBrowser, Toast.LENGTH_SHORT).show();
            return;
        }

        // create chooser
        Intent chooserIntent = Intent.createChooser(intents.remove(0), cntx.getString(R.string.title_choose));
        chooserIntent.putExtra(Intent.EXTRA_INITIAL_INTENTS, intents.toArray(new Parcelable[0]));

        // open
        PackageUtils.startActivity(chooserIntent, R.string.toast_noBrowser, cntx);
    }
}

package com.trianguloy.urlchecker.url;

import com.trianguloy.urlchecker.modules.AModuleDialog;

import java.util.HashMap;
import java.util.Map;

/**
 * Manages an url and extra data associated with it
 * I don't like this approach, but unfortunately I can't think of something better
 */
public class UrlData {

    // ------------------- url -------------------

    public final String url;

    public UrlData(String url) {
        this.url = url == null ? "" : url;
    }

    // ------------------- optional data -------------------

    /**
     * The module that triggered this data (null if internal)
     */
    public AModuleDialog trigger;

    /**
     * If set, the module that triggers the update will be notified (all callbacks)
     */
    public boolean triggerOwn = true;

    public UrlData dontTriggerOwn() {
        triggerOwn = false;
        return this;
    }

    /**
     * If set, the url will not be changed (future setUrl calls will be ignored)
     */
    public boolean disableUpdates = false;

    public UrlData disableUpdates() {
        disableUpdates = true;
        return this;
    }

    /**
     * If set, this update is considered 'minor' and modules may decide to ignore or merge it with the previous one
     */
    public boolean minorUpdate = false;

    public UrlData asMinorUpdate() {
        minorUpdate = true;
        return this;
    }

    // ------------------- extra data -------------------

    private final Map<String, String> extraData = new HashMap<>();

    /**
     * saves a key-value data, will be kept with automatic updates (but not with manual ones)
     */
    public UrlData putData(String key, String value) {
        extraData.put(key, value);
        return this;
    }

    /**
     * gets a key-value data, those set on this update or previous automatic ones
     */
    public String getData(String key) {
        return extraData.get(key);
    }

    /**
     * adds all data from the parameter into this object
     */
    public void mergeData(UrlData urlData) {
        extraData.putAll(urlData.extraData);
    }

    @Override
    public String toString() {
        return "UrlData{" + "url='" + url + '\'' +
                ", trigger=" + trigger +
                ", triggerOwn=" + triggerOwn +
                ", disableUpdates=" + disableUpdates +
                ", minorUpdate=" + minorUpdate +
                ", extraData=" + extraData +
                '}';
    }
}

package com.trianguloy.urlchecker.modules;

import android.app.Activity;

import com.trianguloy.urlchecker.dialogs.MainDialog;
import com.trianguloy.urlchecker.fragments.Fragment;
import com.trianguloy.urlchecker.url.UrlData;
import com.trianguloy.urlchecker.utilities.methods.JavaUtils;

import java.util.Map;

/**
 * Base class for a module's dialog fragment.
 */
public abstract class AModuleDialog implements Fragment {

    // ------------------- private data -------------------

    private final MainDialog dialog;

    // ------------------- initialization -------------------

    public AModuleDialog(MainDialog dialog) {
        this.dialog = dialog;
    }

    // ------------------- abstract functions -------------------

    /**
     * Prepare a new url. This will always be called for each new module.
     */
    public void onPrepareUrl(UrlData urlData) {
    }

    /**
     * Analyze and optionally modify an url. This may not be called for new modules.
     * To modify the url call the setNewUrl callback. It will return true iff you can stop processing changes (false if you need to continue).
     * > if(setNewUrl.apply(new UrlData(""))) return;
     */
    public void onModifyUrl(UrlData urlData, JavaUtils.Function<UrlData, Boolean> setNewUrl) {
    }

    /**
     * Update UI and all needed for this final url. This will only be called for the final shown url.
     */
    public void onDisplayUrl(UrlData urlData) {
    }

    /**
     * Last call for any update a module may need (like the drawer module needing to know how many modules are visible).
     */
    public void onFinishUrl(UrlData urlData) {
    }

    // ------------------- utilities -------------------

    /**
     * @return this activity context
     */
    public final Activity getActivity() {
        return dialog;
    }

    /**
     * @return the current url
     */
    protected final String getUrl() {
        return dialog.getUrl();
    }

    /**
     * Changes the current url. (no extra data)
     *
     * @param url new url
     */
    protected final void setUrl(String url) {
        setUrl(new UrlData(url));
    }

    /**
     * Changes the current url.
     *
     * @param urlData new url and data
     */
    protected final void setUrl(UrlData urlData) {
        urlData.trigger = this;
        dialog.onNewUrl(urlData);
    }

    /**
     * saves global data
     */
    public void putData(String key, String value) {
        dialog.globalData.put(key, value);
    }

    /**
     * gets global data
     */
    public String getData(String key) {
        return dialog.globalData.get(key);
    }

    /**
     * returns the global data map, for advanced uses
     */
    public Map<String, String> getGlobalData() {
        return dialog.globalData;
    }

    /**
     * Changes this module visibility
     */
    protected final void setVisibility(boolean visible) {
        dialog.setModuleVisibility(this, visible);
    }

}

